from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(a, b, limit):
            # limit is k + 1
            S = limit
            m = min(a, S - 1)
            if m <= 0:
                return 0
            x0 = S - b
            if x0 >= m:
                return m * b
            elif x0 < 1:
                return m * S - m * (m + 1) // 2
            else:
                k_prime = m - x0
                return m * b - k_prime * (k_prime + 1) // 2

        # For maximums
        # L_max[i] is the index of the previous element strictly greater than nums[i]
        L_max = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                L_max[i] = stack[-1]
            stack.append(i)

        # R_max[i] is the index of the next element greater than or equal to nums[i]
        R_max = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            if stack:
                R_max[i] = stack[-1]
            stack.append(i)

        total_max_sum = 0
        for i in range(n):
            a = i - L_max[i]
            b = R_max[i] - i
            cnt = count_pairs(a, b, k + 1)
            total_max_sum += nums[i] * cnt

        # For minimums
        # L_min[i] is the index of the previous element strictly smaller than nums[i]
        L_min = [-1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            if stack:
                L_min[i] = stack[-1]
            stack.append(i)

        # R_min[i] is the index of the next element smaller than or equal to nums[i]
        R_min = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            if stack:
                R_min[i] = stack[-1]
            stack.append(i)

        total_min_sum = 0
        for i in range(n):
            a = i - L_min[i]
            b = R_min[i] - i
            cnt = count_pairs(a, b, k + 1)
            total_min_sum += nums[i] * cnt

        return total_max_sum + total_min_sum
